const LEVELS = ["debug", "info", "warn", "error"];

function toLogEvent(level, event, fields = {}, now = "2026-09-21T10:15:02.114Z") {
  // [[edit]]
  // 1. Throw new TypeError(`unknown level: ${level}`) if level is not in LEVELS.
  const out = { ts: now, level, event };
