codeExercise.solution:
const RESERVED = ["ts", "level", "event"];
const LEVELS = ["debug", "info", "warn", "error"];

function toLogEvent(level, event, fields = {}, now = "2026-09-21T10:15:02.114Z") {
  if (!LEVELS.includes(level)) throw new TypeError(`unknown level: ${level}`);
  const out = { ts: now, level, event };
  for (const [key, value] of Object.entries(fields || {})) {
    if (RESERVED.includes(key) || value === undefined) continue;
    out[key] = value instanceof Error ? { name: value.name, message: value.message } : value;
  }
  return out;
}

