describe("toLogEvent", () => {
  it("typical: builds a schema-conforming event", () => {
    expect(toLogEvent("info", "order.created", { requestId: "req-1", orderId: 8812, durationMs: 41 }))
      .toEqual({ ts: "2026-09-21T10:15:02.114Z", level: "info", event: "order.created",
                 requestId: "req-1", orderId: 8812, durationMs: 41 });
  });
  it("boundary: reserved keys cannot be overwritten and Errors are serialised", () => {
    expect(toLogEvent("error", "order.failed", { level: "debug", event: "oops", err: new TypeError("price is null") }))
      .toEqual({ ts: "2026-09-21T10:15:02.114Z", level: "error", event: "order.failed",
                 err: { name: "TypeError", message: "price is null" } });
  });
  it("boundary: undefined fields are dropped, null is kept", () => {
    expect(toLogEvent("warn", "order.slow", { couponCode: undefined, storeId: null }))
      .toEqual({ ts: "2026-09-21T10:15:02.114Z", level: "warn", event: "order.slow", storeId: null });
  });
  it("empty: no fields gives only the base keys", () => {
    expect(toLogEvent("debug", "menu.cache_hit"))
      .toEqual({ ts: "2026-09-21T10:15:02.114Z", level: "debug", event: "menu.cache_hit" });
  });
  it("rejects an unknown level", () => {
    expect(() => toLogEvent("fatal", "x.y")).toThrow("unknown level: fatal");
  });
});

