codeExercise.solution:
function redSummary(requests, windowSec) {
  if (!requests || requests.length === 0) {
    return { rate: 0, errorRate: 0, p50: null, p99: null };
  }
  const sorted = requests.map((r) => r.durationMs).sort((a, b) => a - b);
  const pct = (p) => sorted[Math.ceil((p / 100) * sorted.length) - 1];
  const errors = requests.filter((r) => r.status >= 500).length;
  return {
    rate: requests.length / windowSec,
    errorRate: errors / requests.length,
    p50: pct(50),
    p99: pct(99),
  };
}

