const TRACEPARENT = /^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/;

function parseTraceparent(header) {
  if (typeof header !== "string") return null;
  const m = TRACEPARENT.exec(header.trim());
  if (!m) return null;
  const [, version, traceId, parentId, flags] = m;
  // [[edit]]
  // Reject version "ff" and all-zero traceId or parentId.
  // sampled is the lowest bit of the flags byte.
  return { traceId, parentId, sampled: true };
  // [[/edit]]
}

codeExercise.solution:
function parseTraceparent(header) {
  if (typeof header !== "string") return null;
  const m = /^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/.exec(header.trim());
  if (!m) return null;
  const [, version, traceId, parentId, flags] = m;
  if (version === "ff") return null;
  if (/^0+$/.test(traceId) || /^0+$/.test(parentId)) return null;
  return { traceId, parentId, sampled: (parseInt(flags, 16) & 1) === 1 };
}

