codeExercise.starterCode:
// span and children are { start, end } in ms from the trace start
function selfTime(span, children) {
  // [[edit]]
  // 1. Clip each child to [span.start, span.end]; drop empty intervals.
  // 2. Sort by start and merge overlapping intervals.
  // 3. Return the parent duration minus the merged (covered) time.
  return span.end - span.start;
  // [[/edit]]
}

codeExercise.solution:
function selfTime(span, children) {
  const clipped = children
    .map((c) => [Math.max(c.start, span.start), Math.min(c.end, span.end)])
    .filter(([s, e]) => e > s)
    .sort((a, b) => a[0] - b[0]);
  let covered = 0, curStart = null, curEnd = null;
  for (const [s, e] of clipped) {
    if (curEnd === null || s > curEnd) {
      if (curEnd !== null) covered += curEnd - curStart;
      curStart = s; curEnd = e;
    } else {
      curEnd = Math.max(curEnd, e);
    }
  }
  if (curEnd !== null) covered += curEnd - curStart;
  return span.end - span.start - covered;
}

