codeExercise.solution:
function shouldKeepTrace(trace, random, baseRate = 0.1, slowMs = 1000) {
  if (!trace || !trace.spans || trace.spans.length === 0) return false;
  if (trace.spans.some((s) => s.status === "error")) return true;
  const root = trace.spans.find((s) => s.parentId === null);
  if (root && root.durationMs >= slowMs) return true;
  return random() < baseRate;
}

