  it("boundary: root exactly at the slow threshold is kept", () => {
    const t = { spans: [{ parentId: null, durationMs: 1000, status: "ok" }] };
    expect(shouldKeepTrace(t, never)).toBe(true);
  });
  it("boundary: a slow CHILD alone does not make the trace slow", () => {
    const t = { spans: [{ parentId: null, durationMs: 400, status: "ok" }, { parentId: "a", durationMs: 1500, status: "ok" }] };
    expect(shouldKeepTrace(t, never)).toBe(false);
  });
  it("empty: a trace with no spans is dropped", () => {
    expect(shouldKeepTrace({ spans: [] }, always)).toBe(false);
    expect(shouldKeepTrace(null, always)).toBe(false);
  });
});

