// The DB client is synchronous here to keep the exercise focused; production code awaits each query.
function loadHistory(userId, db) {
  const orders = db.query("SELECT id, placed_at FROM orders WHERE user_id = ?", [userId]);
  if (orders.length === 0) return [];
  const ids = orders.map((o) => o.id);
  const items = db.query("SELECT order_id, name FROM order_items WHERE order_id IN (?)", [ids]);
  return orders.map((o) => ({ ...o, items: items.filter((i) => i.order_id === o.id).map((i) => i.name) }));
}

describe("loadHistory", () => {
  function fakeDb(orders, items) {
    return { query: jest.fn((sql) => (sql.includes("FROM orders") ? orders : items)) };
  }
  it("uses exactly two queries no matter how many orders", () => {
    const orders = Array.from({ length: 250 }, (_, i) => ({ id: i + 1, placed_at: "2026-09-01" }));
    const db = fakeDb(orders, [{ order_id: 7, name: "flat-white" }]);
    const result = loadHistory("u-31", db);
    expect(db.query).toHaveBeenCalledTimes(2);
    expect(result).toHaveLength(250);
    expect(result[6].items).toEqual(["flat-white"]);
  });
  it("attaches the right items to the right order", () => {
    const db = fakeDb([{ id: 1, placed_at: "a" }, { id: 2, placed_at: "b" }],
      [{ order_id: 2, name: "muffin" }, { order_id: 1, name: "cold-brew" }, { order_id: 2, name: "oat-milk" }]);
    expect(loadHistory("u-17", db)).toEqual([
      { id: 1, placed_at: "a", items: ["cold-brew"] },
      { id: 2, placed_at: "b", items: ["muffin", "oat-milk"] },
    ]);
  });
  it("makes one query and returns [] for a user with no orders", () => {
    const db = fakeDb([], []);
    expect(loadHistory("u-new", db)).toEqual([]);
    expect(db.query).toHaveBeenCalledTimes(1);
  });
});

