describe("applyCartResponse ignores stale responses", () => {
  const initial = { items: ["flat-white", "oat-milk"], appliedSeq: 0, staleDropped: 0 };

  it("applies responses that arrive in order", () => {
    const s1 = applyCartResponse(initial, { requestSeq: 1, items: ["flat-white", "oat-milk", "muffin"] });
    const s2 = applyCartResponse(s1, { requestSeq: 2, items: ["flat-white", "muffin"] });
    expect(s2).toEqual({ items: ["flat-white", "muffin"], appliedSeq: 2, staleDropped: 0 });
  });
  it("drops an older response that arrives after a newer one", () => {
    const newer = applyCartResponse(initial, { requestSeq: 2, items: ["flat-white", "muffin"] });
    const after = applyCartResponse(newer, { requestSeq: 1, items: ["flat-white", "oat-milk", "muffin"] });
    expect(after.items).toEqual(["flat-white", "muffin"]);
    expect(after.staleDropped).toBe(1);
  });
  it("treats a duplicate of the applied response as stale", () => {
    const s1 = applyCartResponse(initial, { requestSeq: 3, items: [] });
    const dup = applyCartResponse(s1, { requestSeq: 3, items: ["cold-brew"] });
    expect(dup).toEqual({ items: [], appliedSeq: 3, staleDropped: 1 });
  });
  it("does not mutate the previous state", () => {
    applyCartResponse(initial, { requestSeq: 1, items: [] });
    expect(initial).toEqual({ items: ["flat-white", "oat-milk"], appliedSeq: 0, staleDropped: 0 });
  });
});

