codeExercise.solution:
function scoreHypothesis(requests, predicate) {
  const isFailure = (r) => r.status >= 500;
  const failing = requests.filter(isFailure);
  const succeeding = requests.filter((r) => !isFailure(r));
  const explained = failing.filter(predicate).length;
  const falsePositives = succeeding.filter(predicate).length;
  return {
    failing: failing.length,
    explained,
    falsePositives,
    explainsAll: failing.length > 0 && explained === failing.length && falsePositives === 0,
  };
}

