describe("scoreHypothesis", () => {
  const reqs = [
    { status: 500, store: "harbor",  item: "pumpkin-latte", instance: "api-2" },
    { status: 500, store: "harbor",  item: "pumpkin-latte", instance: "api-1" },
    { status: 201, store: "harbor",  item: "flat-white",    instance: "api-2" },
    { status: 201, store: "midtown", item: "pumpkin-latte", instance: "api-2" },
    { status: 404, store: "airport", item: "cold-brew",     instance: "api-1" },
  ];
  it("typical: the true cause explains every failure and matches no successes", () => {
    expect(scoreHypothesis(reqs, (r) => r.store === "harbor" && r.item === "pumpkin-latte"))
      .toEqual({ failing: 2, explained: 2, falsePositives: 0, explainsAll: true });
  });
  it("typical: a symptom-level hypothesis (instance) matches successes too", () => {
    expect(scoreHypothesis(reqs, (r) => r.instance === "api-2"))
      .toEqual({ failing: 2, explained: 1, falsePositives: 2, explainsAll: false });
  });
  it("boundary: a half-right hypothesis (store only) explains all failures but not the unaffected harbor order", () => {
    expect(scoreHypothesis(reqs, (r) => r.store === "harbor"))
      .toEqual({ failing: 2, explained: 2, falsePositives: 1, explainsAll: false });
  });
  it("boundary: a 4xx counts as a success, not a failure", () => {
    expect(scoreHypothesis(reqs, (r) => r.store === "airport"))
      .toEqual({ failing: 2, explained: 0, falsePositives: 1, explainsAll: false });
  });
  it("empty: no requests means nothing can be explained", () => {
    expect(scoreHypothesis([], () => true))
      .toEqual({ failing: 0, explained: 0, falsePositives: 0, explainsAll: false });
  });
});
